import { Injectable } from '@angular/core';

@Injectable({
  providedIn: 'root'
})
export class SidebarService {
  
  // Mapping of routes to their required permissions
  private routePermissions: { [key: string]: string } = {
    'dashboard': 'dashboard.index',
    'users': 'user.index',
    'employees': 'employee.index',
    'departments': 'department.index',
    'tasks': 'task.index',
    'my-tasks': 'MyTasks.index', // My Tasks uses specific permission
    'all-tasks': 'allTasks.index', // All Tasks uses specific permission
    'partners': 'partners.index',
    'visits': 'visits.index',
    'travel': 'travel.index', 
    'meetings': 'meeting.index',
    'my-calendar': 'calendar.events.get',
    'calendar': 'calendar.index',
    'letters': 'letter.index',
    'letters-approval': 'letterApproval.index', // Letters approval uses specific permission
    'documents': 'documents.index',
    'workflow': 'workFlow.index',
    'roles': 'admin.index',
  };

  // Get permission for a specific route
  getRoutePermission(route: string): string | null {
    return this.routePermissions[route] || null;
  }

  // Get all route permissions
  getAllRoutePermissions(): { [key: string]: string } {
    return { ...this.routePermissions };
  }

  // Check if a route has a permission requirement
  hasPermissionRequirement(route: string): boolean {
    return this.routePermissions.hasOwnProperty(route);
  }

  // Get all available routes (for debugging)
  getAvailableRoutes(): string[] {
    return Object.keys(this.routePermissions);
  }
}
