import { Component, OnInit, signal, Output, EventEmitter, Input, OnDestroy } from '@angular/core';
import { Router, NavigationEnd } from '@angular/router';
import { filter } from 'rxjs/operators';
import { TranslationService } from '../../../services/translation.service';
import { LangService } from '../../../services/lang.service';
import { AuthService } from '../../../services/auth.service';
import { ProfileService, UserProfile } from '../../../services/profile.service';
import { ImageService } from '../../../services/image.service';
import { SidebarService } from '../../../services/sidebar.service';
import { NotificationDropdownComponent } from '../notification-dropdown/notification-dropdown.component';
import { AddNotificationModalComponent } from '../add-notification-modal/add-notification-modal.component';

@Component({
  selector: 'app-sidebar',
  templateUrl: './sidebar.component.html',
  styleUrls: ['./sidebar.component.css'],
  standalone: false
})
export class SidebarComponent implements OnInit, OnDestroy {
  @Input() set rtl(value: boolean) {
    this.isRTL.set(value);
  }
  
  @Input() set isMobile(value: boolean) {
    this._isMobile.set(value);
  }
  
  @Input() set mobileOpen(value: boolean) {
    this._mobileOpen.set(value);
  }
  
  @Output() collapsedChange = new EventEmitter<boolean>();
  @Output() logoutConfirmRequested = new EventEmitter<void>();
  @Output() notificationModalRequested = new EventEmitter<void>();
  @Output() mobileSidebarClose = new EventEmitter<void>();
  
  isCollapsed = signal(false);
  isExpanded = signal(false); // For small screen expansion
  currentLang = signal<'ar' | 'en'>('en');
  isRTL = signal(false);
  _isMobile = signal(false);
  _mobileOpen = signal(false);
  
  // User profile data
  userProfile = signal<UserProfile | null>(null);
  
  // Submenu state
  openSubmenus = signal<Set<string>>(new Set());

  constructor(
    private router: Router,
    private translationService: TranslationService,
    private langService: LangService,
    private authService: AuthService,
    private profileService: ProfileService,
    private imageService: ImageService,
    private sidebarService: SidebarService
  ) {}

  ngOnInit(): void {
    // Subscribe to language changes
    this.langService.currentLang$.subscribe((lang: 'ar' | 'en') => {
      this.currentLang.set(lang);
      this.isRTL.set(lang === 'ar');
    });
    
    // Load user profile
    this.loadUserProfile();
    
    // Subscribe to route changes to manage submenu states
    this.router.events
      .pipe(filter(event => event instanceof NavigationEnd))
      .subscribe(() => {
        this.updateSubmenuStates();
      });
    
  }

  ngOnDestroy(): void {
    // No cleanup needed since we removed resize listener
  }

  private loadUserProfile(): void {
    this.profileService.getProfile().subscribe({
      next: (response) => {
        if (response.success) {
          this.userProfile.set(response.data);
        }
      },
      error: (error) => {
        console.error('Error loading user profile:', error);
      }
    });
  }

  // Check if sidebar should be visible (not hidden on mobile)
  isSidebarVisible(): boolean {
    if (this._isMobile()) {
      return this._mobileOpen();
    }
    return true; // Always visible on desktop
  }

  toggleCollapse(): void {
    this.isCollapsed.update(current => !current);
    this.collapsedChange.emit(this.isCollapsed());
  }

  toggleExpand(): void {
    // For small screens, toggle between collapsed and expanded
    this.isExpanded.update(current => !current);
  }

  closeMobileSidebar(): void {
    this.mobileSidebarClose.emit();
  }

  isActiveRoute(route: string): boolean {
    const currentUrl = this.router.url;
    
    // Special handling for letters submenu
    if (route === 'letters') {
      // Consider parent active on /letters and any sub-route under /letters/*
      return currentUrl === '/letters' || currentUrl.startsWith('/letters/');
    }
    
    if (route === 'letters/approval') {
      // Only match exact /letters/approval path
      return currentUrl === '/letters/approval';
    }
    
    // For other routes, use exact matching
    return currentUrl === `/${route}` || currentUrl.startsWith(`/${route}/`);
  }

  translate(key: string): string {
    return this.translationService.translate(key);
  }

  openLogoutConfirm(): void {
    this.logoutConfirmRequested.emit();
  }

  openNotificationModal(): void {
    this.notificationModalRequested.emit();
  }

  closeNotificationModal(): void {
    // No local modal state to manage, so this method is effectively a no-op
  }

  onSendNotification(notificationData: any): void {
    console.log('Sending notification:', notificationData);
    // Here you would typically send the notification to your backend
    // For now, we'll just log it and close the modal
    this.closeNotificationModal();
  }

  getFullName(): string {
    const profile = this.userProfile();
    if (profile) {
      return `${profile.firstName} ${profile.lastName}`;
    }
    return 'User';
  }

  getPrimaryRole(): string {
    const profile = this.userProfile();
    if (profile && profile.roles && profile.roles.length > 0) {
      return profile.roles[0];
    }
    return 'User';
  }

  getUserImageUrl(): string {
    const profile = this.userProfile();
    if (profile) {
      return this.imageService.getImageUrl(profile.imageUrl, `${profile.firstName} ${profile.lastName}`);
    }
    return this.imageService.getImageUrl();
  }

  getUserInitials(): string {
    const profile = this.userProfile();
    if (profile) {
      return this.imageService.getUserInitials(profile.firstName, profile.lastName);
    }
    return 'U';
  }

  // Check if user has permission for a specific route
  hasRoutePermission(route: string): boolean {
    // Dashboard and My Calendar are always visible (mandatory for everyone)
    if (route === 'dashboard' || route === 'my-calendar') {
      return true;
    }
    
    const requiredPermission = this.sidebarService.getRoutePermission(route);
    if (!requiredPermission) {
      return false; // If no permission is defined, hide the route by default
    }
    return this.authService.hasPermission(requiredPermission);
  }

  // Get permission for a route (used in template)
  getRoutePermission(route: string): string | string[] {
    const permission = this.sidebarService.getRoutePermission(route);
    return permission || ''; // Return empty string if no permission is required
  }

  // Submenu functionality
  toggleSubmenu(menuName: string): void {
    // For letters, ensure we link to the route when outside the group
    if (menuName === 'letters') {
      const currentUrl = this.router.url;
      const isInLettersGroup = currentUrl === '/letters' || currentUrl.startsWith('/letters/');
      
      if (!isInLettersGroup) {
        // Navigate into the letters section first; submenu will sync open via updateSubmenuStates
        this.router.navigate(['/letters']);
        return;
      }
    }
    
    const currentOpen = this.openSubmenus();
    const newOpen = new Set(currentOpen);
    
    if (newOpen.has(menuName)) {
      newOpen.delete(menuName);
    } else {
      newOpen.add(menuName);
    }
    
    this.openSubmenus.set(newOpen);
  }

  isSubmenuOpen(menuName: string): boolean {
    return this.openSubmenus().has(menuName);
  }

  private updateSubmenuStates(): void {
    const currentUrl = this.router.url;
    const currentOpen = this.openSubmenus();
    const newOpen = new Set(currentOpen);
    
    // Auto-open letters submenu when on letters routes
    if (currentUrl === '/letters' || currentUrl.startsWith('/letters/')) {
      if (!newOpen.has('letters')) {
        newOpen.add('letters');
      }
    } else {
      // Close letters submenu when not on letters routes
      if (newOpen.has('letters')) {
        newOpen.delete('letters');
      }
    }
    
    // Update the submenu state if it changed
    if (newOpen.size !== currentOpen.size || 
        Array.from(newOpen).some(item => !currentOpen.has(item))) {
      this.openSubmenus.set(newOpen);
    }
  }

}
