import { Observable } from 'rxjs';
import { environment } from './../../environments/environment';
import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';

@Injectable({
  providedIn: 'root',
})
export class NotificationsService {
  private apiUrl = `${environment.apiBaseUrl}/Notification`;
  constructor(private http: HttpClient) {}

  /**
   * Plays the notification sound
   */
  playNotificationSound(): void {
    try {
      const audio = new Audio('assets/sounds/tone.mp3');
      audio.play().catch((error) => {
        // Handle autoplay restrictions - browsers may block autoplay
        console.warn('Could not play notification sound:', error);
      });
    } catch (error) {
      console.warn('Error creating audio element:', error);
    }
  }

  getUserNotification(userId?: string): Observable<any> {
    // Try without userId parameter first, as the API might use the authenticated user's token
    return this.http.get<any>(`${this.apiUrl}/user`);
  }

  markAsRead(id: number): Observable<any> {
    return this.http.patch<any>(`${this.apiUrl}/${id}`, {});
  }
  markAllAsRead(): Observable<any> {
    return this.http.patch<any>(`${this.apiUrl}/mark-all`, {});
  }
  addNotification(data: any): Observable<any> {
    return this.http.post<any>(`${this.apiUrl}`, data);
  }

  getFilteredNotifications(
    page: number = 1,
    pageSize: number = 10,
    searchTerm: string = ''
  ): Observable<any> {
    const params: any = {
      Page: page.toString(),
      PageSize: pageSize.toString(),
    };

    if (searchTerm && searchTerm.trim() !== '') {
      params.SearchTerm = searchTerm.trim();
    }

    return this.http.get<any>(`${this.apiUrl}/user/filtered`, { params });
  }
}
