import { Component, Input, OnInit, OnDestroy, signal, HostListener } from '@angular/core';
import { Router } from '@angular/router';
import { TranslationService } from '../../../services/translation.service';
import { NotificationsService } from '../../../services/notifications.service';
import { AuthService } from '../../../services/auth.service';

enum NotificationReferenceType {
  None = 0,
  Meeting = 1,
  Task = 2,
  Visit = 3,
  Travel = 4,
}

interface Notification {
  id: number;
  title: string;
  message: string;
  timestamp: Date;
  isRead: boolean;
  type: 'info' | 'success' | 'warning' | 'error';
  referenceId?: number | null;
  referenceType?: number;
}

interface UserNotification {
  id: number;
  userId: string;
  notificationId: number;
  isRead: boolean;
  readAt: string | null;
}

interface ApiNotification {
  id: number;
  title: string;
  message: string;
  type: string;
  createdAt: string;
  referenceId?: number | null;
  referenceType?: number;
  userNotifications: UserNotification[];
}

@Component({
  selector: 'app-notification-dropdown',
  templateUrl: './notification-dropdown.component.html',
  styleUrls: ['./notification-dropdown.component.css'],
  standalone: false,
})
export class NotificationDropdownComponent implements OnInit, OnDestroy {
  @Input() isRTL = false;

  isOpen = signal(false);
  notifications: Notification[] = [];
  unreadCount = signal(0);
  isLoading = signal(false);
  error = signal('');
  currentUserId: string = '';
  private previousNotificationIds: Set<number> = new Set();
  isBellShaking = signal(false);
  private pollingInterval?: any;
  private readonly POLLING_INTERVAL_MS = 30000; // 30 seconds

  constructor(
    private translationService: TranslationService,
    private notificationService: NotificationsService,
    private authService: AuthService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.getCurrentUserId();
    this.loadNotifications();
    this.startPolling();
  }

  ngOnDestroy(): void {
    this.stopPolling();
  }

  /**
   * Start polling for new notifications
   */
  private startPolling(): void {
    // Poll every 30 seconds for new notifications
    this.pollingInterval = setInterval(() => {
      this.checkForNewNotifications();
    }, this.POLLING_INTERVAL_MS);
  }

  /**
   * Stop polling for new notifications
   */
  private stopPolling(): void {
    if (this.pollingInterval) {
      clearInterval(this.pollingInterval);
      this.pollingInterval = undefined;
    }
  }

  /**
   * Check for new notifications without showing loading state (silent check)
   */
  private checkForNewNotifications(): void {
    this.notificationService.getUserNotification().subscribe({
      next: (response) => {
        if (response.success && response.data) {
          // Process notifications
          const newNotifications = response.data.map(
            (apiNotification: ApiNotification) => {
              const userNotification = apiNotification.userNotifications[0];
              const isRead = userNotification ? userNotification.isRead : false;

              // Fix timezone by adding 'Z' if not present
              const dateStr =
                apiNotification.createdAt.includes('Z') ||
                apiNotification.createdAt.includes('+') ||
                apiNotification.createdAt.includes('-', 10)
                  ? apiNotification.createdAt
                  : apiNotification.createdAt + 'Z';

              return {
                id: apiNotification.id,
                title: apiNotification.title,
                message: apiNotification.message,
                timestamp: new Date(dateStr),
                isRead: isRead,
                type: apiNotification.type.toLowerCase() as
                  | 'info'
                  | 'success'
                  | 'warning'
                  | 'error',
                referenceId: apiNotification.referenceId,
                referenceType: apiNotification.referenceType,
              };
            }
          );

          // Detect new notifications and trigger sound/animation
          this.detectNewNotifications(newNotifications);

          // Update notifications list
          this.notifications = newNotifications;
          this.updateUnreadCount();
        }
      },
      error: (err) => {
        // Silently handle errors during polling - don't show error messages
        // Only log if it's not the expected "No Notification To Show" error
        if (err.status !== 400 || err.error !== 'No Notification To Show') {
          console.error('Error checking for new notifications:', err);
        }
      },
    });
  }

  private getCurrentUserId(): void {
    // Get current user ID from auth service or local storage
    const currentUser = this.authService.getCurrentUser();
    if (currentUser) {
      this.currentUserId = currentUser.id;
    } else {
      // Fallback: try to get from localStorage or other sources
      const storedUser = localStorage.getItem('user');
      if (storedUser) {
        try {
          const user = JSON.parse(storedUser);
          this.currentUserId = user.id;
        } catch (e) {
          console.error('Error parsing stored user:', e);
        }
      }
    }
  }

  private loadNotifications(): void {
    this.isLoading.set(true);
    this.error.set('');

    this.notificationService.getUserNotification().subscribe({
      next: (response) => {
        if (response.success && response.data) {
          // Process notifications - the API returns notifications for the authenticated user
          const newNotifications = response.data.map(
            (apiNotification: ApiNotification) => {
              // Since the API returns notifications for the authenticated user,
              // we can use the first (and likely only) userNotification entry
              const userNotification = apiNotification.userNotifications[0];

              // If no user notification found, assume unread
              const isRead = userNotification ? userNotification.isRead : false;

              // Fix timezone by adding 'Z' if not present
              const dateStr =
                apiNotification.createdAt.includes('Z') ||
                apiNotification.createdAt.includes('+') ||
                apiNotification.createdAt.includes('-', 10)
                  ? apiNotification.createdAt
                  : apiNotification.createdAt + 'Z';

              return {
                id: apiNotification.id,
                title: apiNotification.title,
                message: apiNotification.message,
                timestamp: new Date(dateStr),
                isRead: isRead,
                type: apiNotification.type.toLowerCase() as
                  | 'info'
                  | 'success'
                  | 'warning'
                  | 'error',
                referenceId: apiNotification.referenceId,
                referenceType: apiNotification.referenceType,
              };
            }
          );

          // Detect new notifications
          this.detectNewNotifications(newNotifications);

          this.notifications = newNotifications;
          this.updateUnreadCount();
        } else {
          this.notifications = [];
          this.error.set('Failed to load notifications');
        }
        this.isLoading.set(false);
      },
      error: (err) => {
        // Handle the case where there are no notifications (API returns 400 with "No Notification To Show")
        if (err.status === 400 && err.error === 'No Notification To Show') {
          this.notifications = [];
          this.error.set(''); // Clear error message since this is expected
        } else {
          console.error('Error loading notifications:', err);
          this.error.set('Failed to load notifications');
        }

        this.isLoading.set(false);
      },
    });
  }

  toggleDropdown(): void {
    this.isOpen.update((current) => !current);
  }

  closeDropdown(): void {
    this.isOpen.set(false);
  }

  @HostListener('document:click', ['$event'])
  onDocumentClick(event: Event): void {
    const target = event.target as HTMLElement;
    if (!this.isOpen()) return;

    // Check if click is outside the notification container
    if (!target.closest('.notification-container')) {
      this.closeDropdown();
    }
  }

  @HostListener('document:keydown.escape', ['$event'])
  onEscapeKey(event: Event): void {
    if (this.isOpen()) {
      this.closeDropdown();
    }
  }

  markAsRead(notificationId: number): void {
    this.notificationService.markAsRead(notificationId).subscribe({
      next: (response) => {
        console.log('Notification marked as read:', response);
        // Update local state immediately for better UX
        const notification = this.notifications.find(
          (n) => n.id === notificationId
        );
        if (notification) {
          notification.isRead = true;
          this.updateUnreadCount();
        }
      },
      error: (err) => {
        console.error('Error marking notification as read:', err);
        // Show error to user
        this.error.set('Failed to mark notification as read');
      },
    });
  }

  markAllAsRead(): void {
    this.notificationService.markAllAsRead().subscribe({
      next: (response) => {
        console.log('All notifications marked as read:', response);
        // Update local state immediately for better UX
        this.notifications.forEach((notification) => {
          notification.isRead = true;
        });
        this.updateUnreadCount();
      },
      error: (err) => {
        console.error('Error marking all notifications as read:', err);
        // Show error to user
        this.error.set('Failed to mark all notifications as read');
      },
    });
  }

  private updateUnreadCount(): void {
    if (this.notifications && Array.isArray(this.notifications)) {
      // Only count notifications that are NOT read (isRead: false)
      const unreadCount = this.notifications.filter(
        (notification: Notification) => !notification.isRead
      ).length;
      this.unreadCount.set(unreadCount);
    } else {
      this.unreadCount.set(0);
    }
  }

  /**
   * Detects new notifications and triggers sound/animation
   */
  private detectNewNotifications(newNotifications: Notification[]): void {
    // If this is the first load, just store the IDs (don't trigger alert)
    if (this.previousNotificationIds.size === 0) {
      newNotifications.forEach((notification) => {
        this.previousNotificationIds.add(notification.id);
      });
      return;
    }

    // Check for new unread notifications
    const newUnreadNotifications = newNotifications.filter(
      (notification) =>
        !notification.isRead &&
        !this.previousNotificationIds.has(notification.id)
    );

    // If there are new unread notifications, trigger sound and animation
    if (newUnreadNotifications.length > 0) {
      this.triggerNotificationAlert();
    }

    // Update the set of known notification IDs
    this.previousNotificationIds.clear();
    newNotifications.forEach((notification) => {
      this.previousNotificationIds.add(notification.id);
    });
  }

  /**
   * Triggers the notification sound and bell animation
   */
  private triggerNotificationAlert(): void {
    // Play notification sound
    this.notificationService.playNotificationSound();

    // Trigger bell shake animation
    // Reset first to ensure animation restarts
    this.isBellShaking.set(false);
    
    // Use setTimeout to ensure the reset is processed before adding the class
    setTimeout(() => {
      this.isBellShaking.set(true);
      
      // Remove the class after animation completes
      setTimeout(() => {
        this.isBellShaking.set(false);
      }, 600); // Animation duration matches CSS animation
    }, 10);
  }

  getTimeAgo(date: Date | string): string {
    const now = new Date();
    // Parse the date string and treat it as UTC if it doesn't have timezone info
    let notificationDate: Date;
    if (typeof date === 'string') {
      // If the date string doesn't have 'Z' or timezone offset, add 'Z' to treat it as UTC
      const dateStr =
        date.includes('Z') || date.includes('+') || date.includes('-', 10)
          ? date
          : date + 'Z';
      notificationDate = new Date(dateStr);
    } else {
      notificationDate = date;
    }

    // Check if date is valid
    if (isNaN(notificationDate.getTime())) {
      return 'Invalid date';
    }

    const diffInMs = now.getTime() - notificationDate.getTime();
    const diffInSeconds = Math.floor(diffInMs / 1000);
    const diffInMinutes = Math.floor(diffInSeconds / 60);
    const diffInHours = Math.floor(diffInMinutes / 60);
    const diffInDays = Math.floor(diffInHours / 24);

    if (diffInSeconds < 30) return 'Just now';
    if (diffInMinutes < 1) return 'Just now';
    if (diffInMinutes < 60) return `${diffInMinutes}m ago`;
    if (diffInHours < 24) return `${diffInHours}h ago`;
    return `${diffInDays}d ago`;
  }

  getNotificationIcon(type: string): string {
    switch (type) {
      case 'success':
        return '✓';
      case 'warning':
        return '⚠';
      case 'error':
        return '✗';
      default:
        return 'ℹ';
    }
  }

  getNotificationClass(type: string): string {
    return `notification-${type}`;
  }

  translate(key: string): string {
    return this.translationService.translate(key);
  }

  canNavigateToReference(notification: Notification): boolean {
    // Don't show navigation button if referenceType is None (0)
    if (
      !notification.referenceType ||
      notification.referenceType === NotificationReferenceType.None
    ) {
      return false;
    }

    // Don't show navigation button if no referenceId
    if (!notification.referenceId) {
      return false;
    }

    // Check user permission based on referenceType
    const requiredPermission = this.getRequiredPermission(
      notification.referenceType
    );
    if (!requiredPermission) {
      return false;
    }

    return this.authService.hasPermission(requiredPermission);
  }

  private getRequiredPermission(referenceType: number): string | null {
    switch (referenceType) {
      case NotificationReferenceType.Meeting:
        return 'meeting.index';
      case NotificationReferenceType.Task:
        return 'task.index';
      case NotificationReferenceType.Visit:
        return 'visits.index';
      case NotificationReferenceType.Travel:
        return 'travel.index';
      default:
        return null;
    }
  }

  navigateToReference(notification: Notification): void {
    if (!this.canNavigateToReference(notification)) {
      return;
    }

    const referenceId = notification.referenceId;
    const referenceType = notification.referenceType;

    // Mark notification as read before navigating
    if (!notification.isRead) {
      this.markAsRead(notification.id);
    }

    // Navigate based on referenceType
    switch (referenceType) {
      case NotificationReferenceType.Meeting:
        this.router.navigate(['/meetings/details', referenceId]);
        break;
      case NotificationReferenceType.Task:
        this.router.navigate(['/tasks/details', referenceId]);
        break;
      case NotificationReferenceType.Visit:
        this.router.navigate(['/visits/details', referenceId]);
        break;
      case NotificationReferenceType.Travel:
        this.router.navigate(['/travel/details', referenceId]);
        break;
      default:
        console.warn('Unknown referenceType:', referenceType);
    }

    // Close dropdown after navigation
    this.closeDropdown();
  }
}
